begin;
create table public.scheduled_jobs(id uuid primary key default gen_random_uuid(),job_type text not null unique,enabled boolean not null default true,schedule_expression text not null,last_run_at timestamptz,next_run_at timestamptz,failure_streak integer not null default 0,last_success_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.job_runs(id uuid primary key default gen_random_uuid(),scheduled_job_id uuid references public.scheduled_jobs(id) on delete set null,job_type text not null,started_at timestamptz not null default now(),finished_at timestamptz,status text not null check(status in('SUCCESS','PARTIAL','FAILED','SKIPPED','RUNNING')),attempt integer not null default 1,triggered_by text not null check(triggered_by in('SCHEDULE','MANUAL','RETRY','DEPENDENCY')),items_processed integer not null default 0,items_succeeded integer not null default 0,items_partial integer not null default 0,items_failed integer not null default 0,warnings jsonb not null default '[]'::jsonb,errors jsonb not null default '[]'::jsonb,deterministic_key text not null unique,data_version jsonb not null default '{}'::jsonb,duration_ms integer,db_queries integer not null default 0,external_requests integer not null default 0,created_at timestamptz not null default now());
create table public.job_run_items(id uuid primary key default gen_random_uuid(),job_run_id uuid not null references public.job_runs(id) on delete cascade,fund_id uuid references public.funds(id) on delete set null,portfolio_id uuid references public.portfolios(id) on delete set null,status text not null check(status in('SUCCESS','PARTIAL','FAILED','SKIPPED')),message text not null,warning_code text,error_code text,started_at timestamptz not null default now(),finished_at timestamptz not null default now());
create table public.job_locks(lock_key text primary key,job_type text not null,owner_id uuid not null,acquired_at timestamptz not null default now(),locked_until timestamptz not null);
create table public.provider_circuit_breakers(provider text primary key,state text not null check(state in('CLOSED','OPEN','HALF_OPEN')) default 'CLOSED',failure_count integer not null default 0,opened_at timestamptz,retry_after timestamptz,last_error_code text,updated_at timestamptz not null default now());
create table public.data_quality_events(id uuid primary key default gen_random_uuid(),event_key text not null unique,event_type text not null,severity text not null check(severity in('INFO','WARNING','CRITICAL')),fund_id uuid references public.funds(id) on delete cascade,portfolio_id uuid references public.portfolios(id) on delete cascade,message text not null,data_version jsonb not null default '{}'::jsonb,detected_at timestamptz not null default now(),resolved_at timestamptz);
create index job_runs_type_started_idx on public.job_runs(job_type,started_at desc);create index job_run_items_run_idx on public.job_run_items(job_run_id);create index scheduled_jobs_due_idx on public.scheduled_jobs(enabled,next_run_at);
alter table public.scheduled_jobs enable row level security;alter table public.job_runs enable row level security;alter table public.job_run_items enable row level security;alter table public.job_locks enable row level security;alter table public.provider_circuit_breakers enable row level security;alter table public.data_quality_events enable row level security;
create or replace function public.acquire_job_lock(p_lock_key text,p_job_type text,p_owner_id uuid,p_lease_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$ begin insert into public.job_locks(lock_key,job_type,owner_id,locked_until) values(p_lock_key,p_job_type,p_owner_id,now()+make_interval(secs=>least(greatest(p_lease_seconds,1),3600))) on conflict(lock_key) do update set owner_id=excluded.owner_id,job_type=excluded.job_type,acquired_at=now(),locked_until=excluded.locked_until where public.job_locks.locked_until<now();return found;end$$;
create or replace function public.release_job_lock(p_lock_key text,p_owner_id uuid) returns void language sql security definer set search_path=public as $$ delete from public.job_locks where lock_key=p_lock_key and owner_id=p_owner_id $$;
revoke all on function public.acquire_job_lock(text,text,uuid,integer) from public,anon,authenticated;
revoke all on function public.release_job_lock(text,uuid) from public,anon,authenticated;
grant execute on function public.acquire_job_lock(text,text,uuid,integer) to service_role;
grant execute on function public.release_job_lock(text,uuid) to service_role;
insert into public.scheduled_jobs(job_type,schedule_expression,next_run_at) values('KRON_FUND_DISCOVERY','0 4 * * 1,4',now()),('KID_DISCOVERY','20 4 * * *',now()),('KID_PARSING','40 4 * * *',now()),('EXPOSURE_INGESTION','0 5 * * 0',now()),('NAV_INGESTION','0 5 * * 1-5',now()),('PERFORMANCE_METRICS','20 5 * * 1-5',now()),('PORTFOLIO_SNAPSHOT','40 5 * * 1-5',now()),('PORTFOLIO_MONITORING','0 6 * * 1-5',now()),('REBALANCE_EVALUATION','20 6 * * 1-5',now()),('MAINTENANCE_CLEANUP','0 3 * * 0',now()) on conflict(job_type) do nothing;
commit;
